query BulkHirePreview($hires: [BulkHireInput!]!) {
    peopleBulkHirePreview(hires: $hires) {
      committed rows { personId name outcome held changes { key label dated before { ...EntryParts } after { ...EntryParts } } refusal { code message keys } findings { key label level code message review } }
    }
  }
  fragment EntryParts on FormEntry {
    __typename
    ... on TextEntry { key text }
    ... on FlagEntry { key flag }
    ... on ListEntry { key items }
    ... on MoneyEntry { key amountMinor currency }
    ... on SealedEntry { key last4 }
    ... on EmptyEntry { key }
  }
